    for f in sorted(TAGS_DIR.glob("*.yaml")):
        d = yaml.safe_load(f.read_text(encoding="utf-8"))
        if isinstance(d, dict):
            d = d.get("tags") or next((v for v in d.values() if isinstance(v, list)), [])
        items += [x for x in (d or []) if isinstance(x, dict) and x.get("id")]
    seen = {}
    for x in items:
        i = str(x["id"])
        if i not in seen:
            seen[i] = dict(x, syn_ru=list(x.get("syn_ru") or []), syn_en=list(x.get("syn_en") or []))
            continue
        y = seen[i]
        for k in ("ru", "en", "family", "parent"):
            if not y.get(k) and x.get(k):
                y[k] = x[k]
        for k in ("syn_ru", "syn_en"):
            y[k] += [t for t in (x.get(k) or []) if t not in y[k]]
    return seen


def build_index(tags):
    """first-key -> [(keys, tid, term_text, strong)]"""
    idx: dict = {}
    for tid, x in tags.items():
        terms = [x.get("ru"), x.get("en"), *(x.get("syn_ru") or []), *(x.get("syn_en") or [])]
        for t in terms:
            ws = norm_words(str(t), drop_ident=False) if t else []
            if not ws:
                continue
            if len(ws) == 1 and ws[0] in STOP:
                continue
            keys = tuple(term_key(w) for w in ws)
            strong = len(ws) > 1 or len(keys[0][1]) >= STRONG_LEN
            idx.setdefault(keys[0], []).append((keys, tid, " ".join(ws), strong))
    return idx


def match(text_words, idx, cache):
    """-> {tag_id: {term: strong}}"""
    pos = []
    for w in text_words:
        k = cache.get(w)
        if k is None:
            k = cache[w] = token_keys(w)
        pos.append(k)
    found: dict = {}
    for i, ks in enumerate(pos):
        for k in ks:
            for keys, tid, term, strong in idx.get(k, ()):
                if len(keys) == 1 or all(i + j < len(pos) and keys[j] in pos[i + j] for j in range(1, len(keys))):
                    found.setdefault(tid, {})[term] = strong
    return found


def decide(head: dict, body: dict) -> set:
    """Какие теги ставим: title / >=2 разных термина в теле / один сильный термин."""
    out = set(head)
    for tid, terms in body.items():
        if len(terms) >= 2 or any(terms.values()):
            out.add(tid)
    return out


def record_words(title, summary, body_md):
    """-> (слова title, слова тела). Схемные записи в теле не матчатся."""
    head = norm_words((title or "").replace("_", " "), drop_ident=False)
    if _RE_SCHEMA_TITLE.search(title or ""):
        return head, []
    b = body_md or ""
    sm = (summary or "").rstrip("…").strip()
    if sm and sm[:40] not in b:
        b = sm + " . " + b
    return head, norm_words(clean_text(b))


def tag_record(title, summary, body_md, idx, cache):
    hw, bw = record_words(title, summary, body_md)
    return decide(match(hw, idx, cache), match(bw, idx, cache))


def run(con, game=None, quiet=False):
    t0 = time.time()
    tags = load_tags()
    if not tags:
        if not quiet:
            print(f"[tag] нет словаря: {TAGS_DIR}/*.yaml")
        return None
    con.executescript(DDL)
    con.execute("DELETE FROM tags")
    con.executemany("INSERT INTO tags(id,ru,en,family,parent) VALUES(?,?,?,?,?)",
                    [(i, x.get("ru"), x.get("en"), x.get("family"), x.get("parent") or None) for i, x in tags.items()])
    parent = {i: (x.get("parent") or None) for i, x in tags.items()}
    idx = build_index(tags)
    w, p = ("WHERE g.slug=?", [game]) if game else ("", [])
    ids = [r[0] for r in con.execute(f"SELECT e.id FROM entries e JOIN games g ON g.id=e.game_id {w}", p)]
    con.executemany("DELETE FROM record_tags WHERE record_id=?", [(i,) for i in ids])
    rows = con.execute(f"SELECT e.id,e.title,e.summary,e.body_md FROM entries e JOIN games g ON g.id=e.game_id {w}", p).fetchall()
    cache, out, tagged = {}, [], 0
    for r in rows:
        direct = tag_record(r["title"], r["summary"], r["body_md"], idx, cache)
        allt = {t: "auto" for t in direct}
        for t in direct:
            q, hop = parent.get(t), 0
            while q and q in tags and hop < 10:
                allt.setdefault(q, "parent"); q = parent.get(q); hop += 1
        if allt:
            tagged += 1
        out += [(r["id"], t, s) for t, s in allt.items()]
    con.execute("DELETE FROM record_tags WHERE record_id NOT IN (SELECT id FROM entries)")
    con.executemany("INSERT OR REPLACE INTO record_tags(record_id,tag_id,source) VALUES(?,?,?)", out)
    con.commit()
    dt = time.time() - t0
    if not quiet:
        pct = 100 * tagged / max(1, len(rows))
        print(f"[tag] {game or 'все игры'}: записей {len(rows)}, с >=1 тегом {tagged} ({pct:.1f}%), "
              f"тегов в словаре {len(tags)}, связей {len(out)}, {dt:.1f}s")
    return len(rows), tagged, dt


def main():
    C.utf8_stdout()
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--game"); ap.add_argument("--db")
    a = ap.parse_args()
    if a.db:
        C.DB_PATH = Path(a.db)
    con = C.connect()
    run(con, a.game)


if __name__ == "__main__":
    main()

